function validate([grid]) {
  if (!Array.isArray(grid) || grid.length < 1 || grid.length > 15) return 'grid needs 1 to 15 rows.';
  const n = Array.isArray(grid[0]) ? grid[0].length : 0;
  if (n < 1 || n > 15) return 'Each row needs 1 to 15 cells.';
  if (grid.some(row => !Array.isArray(row) || row.length !== n)) return 'All rows must have the same length.';
  if (grid.length * n > 15) return 'grid may have at most 15 cells in total.';
  if (grid.some(row => row.some(v => v !== 0 && v !== 1))) return 'Each cell is 0 or 1.';
  return null;
}

