function removeOnes(grid) {
  const m = grid.length;
  const n = grid[0].length;
  let start = 0;
  const wipe = [];
  for (let i = 0; i < m; i++) {
    for (let j = 0; j < n; j++) {
      if (grid[i][j] === 1) {
        start |= 1 << (i * n + j);
      }
      let lines = 0;
      for (let k = 0; k < n; k++) {
        lines |= 1 << (i * n + k);
      }
      for (let k = 0; k < m; k++) {
        lines |= 1 << (k * n + j);
      }
      wipe.push(lines);
    }
  }

  const steps = new Array(1 << (m * n)).fill(-1);
  steps[start] = 0;
  const queue = [start];
  for (let head = 0; head < queue.length; head++) {
    const mask = queue[head];
    if (mask === 0) {
      return steps[mask];
    }
    for (let cell = 0; cell < m * n; cell++) {
      if ((mask & (1 << cell)) === 0) {
        continue;
      }
      const next = mask & ~wipe[cell];
      if (steps[next] === -1) {
        steps[next] = steps[mask] + 1;
        queue.push(next);
      }
    }
  }
  return steps[0];
}

