  const n = grid[0].length;
  const solve = (g) => {
    let best = Infinity;
    for (let r = 0; r < m; r++) {
      for (let c = 0; c < n; c++) {
        if (g[r][c] !== 1) continue;
        const copy = g.map((row, rr) => row.map((v, cc) => (rr === r || cc === c ? 0 : v)));
        best = Math.min(best, 1 + solve(copy));
      }
    }
    return best === Infinity ? 0 : best;
  };
  return solve(grid);
}

