function generate(rand, size) {
  let m;
  let n;
  if (size === 'large') {
    const shapes = [[3, 5], [5, 3], [3, 4], [4, 3], [2, 7], [7, 2], [1, 15], [15, 1]];
    [m, n] = shapes[Math.floor(rand() * shapes.length)];
  } else {
    m = 1 + Math.floor(rand() * 15);
    n = 1 + Math.floor(rand() * Math.floor(15 / m));
  }
  const density = 0.15 + rand() * 0.8;
  const grid = Array.from({ length: m }, () => Array.from({ length: n }, () => (rand() < density ? 1 : 0)));
  return [grid];
}
